examples.setup:
var saved by rememberSaveable { mutableStateOf("Northwind") }
var name by rememberSaveable { mutableStateOf("Northwind Ltd") }
var email by rememberSaveable { mutableStateOf("team@example.com") }

examples.code:
Scaffold(
    bottomBar = {
        MonarchFormActionsBar(
            dirty = name != saved,
            onSave = { saved = name },
            onDiscard = { name = saved },
        )
    },
) { padding ->
    MonarchTextField(
        value = name,
        onValueChange = { name = it },
        modifier = Modifier.padding(padding),
        label = "Workspace name",
    )
}
